import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolDefinition} from '../../types/ai.js';

const WEATHER: ToolDefinition = {
  name: 'get_weather',
  description: 'Current weather for a location',
  inputSchema: {
    type: 'object',
    properties: {location: {type: 'string'}},
    required: ['location'],
  },
};

const countingExecutor = (): {calls: Record<string, unknown>[]; execute: ToolExecutor} => {
  const calls: Record<string, unknown>[] = [];
  const execute: ToolExecutor = async input => {
    calls.push(input);
    return `sunny in ${String(input.location)}`;
  };
  return {calls, execute};
};

const recordingLogger = (lines: string[]): Logger => {
  const record = (category: string, message: string, fields?: Record<string, unknown>): void =>
    void lines.push(JSON.stringify({category, message, fields}));
  return {debug: record, info: record, warn: record, error: record};
};

describe('ToolRegistry.execute validates input against the registered inputSchema', () => {
  afterEach(() => setLogger());

  it('returns a rejection naming the missing required property and never runs the executor', async () => {
    const registry = new ToolRegistry();
    const tool = countingExecutor();
    registry.register(WEATHER, tool.execute);

    const response = await registry.execute('get_weather', {});

    expect({result: response.result, calls: tool.calls.length}).toEqual({
      result: expect.stringMatching(/location[\s\S]*required|required[\s\S]*location/),
      calls: 0,
    });
  });

  it('rejects a wrong-typed field by path and expected type without echoing the value in the result or the logs', async () => {
    const lines: string[] = [];
    setLogger(recordingLogger(lines));
    const registry = new ToolRegistry();
    const tool = countingExecutor();
    registry.register(WEATHER, tool.execute);
    const identifying = 4155550123;

    const response = await registry.execute('get_weather', {location: identifying});

    expect({
      namesPathAndType: /location/.test(response.result) && /string/.test(response.result),
      resultLeaksValue: response.result.includes(String(identifying)),
      logLeaksValue: lines.some(line => line.includes(String(identifying))),
      calls: tool.calls.length,
    }).toEqual({namesPathAndType: true, resultLeaksValue: false, logLeaksValue: false, calls: 0});
  });

  it('throws at register time for an uncompilable schema, naming the tool', () => {
    const registry = new ToolRegistry();
    const broken: ToolDefinition = {
      name: 'broken_tool',
      description: 'declares a schema no validator can compile',
      inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
    };

    expect(() => registry.register(broken, async () => 'never')).toThrow(/broken_tool/);
  });
});

describe('a rejected tool call is returned to the model rather than ending the conversation', () => {
  it('resolves processMessage after a rejected call and a corrected retry, showing the provider the rejection', async () => {
    const seen: SendMessageParams[] = [];
    const rounds: MessageChunk[][] = [
      [
        {type: 'tool_use', toolCall: {id: 'bad', name: 'get_weather', input: {}}},
        {type: 'stop', stopReason: 'tool_use'},
      ],
      [
        {type: 'tool_use', toolCall: {id: 'good', name: 'get_weather', input: {location: 'Berlin'}}},
        {type: 'stop', stopReason: 'tool_use'},
      ],
      [
        {type: 'text', text: 'It is sunny in Berlin.'},
        {type: 'stop', stopReason: 'end_turn'},
      ],
    ];
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        seen.push(JSON.parse(JSON.stringify(params)) as SendMessageParams);
        for (const chunk of rounds[round++] ?? []) yield chunk;
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };
    const registry = new ToolRegistry();
    registry.register(WEATHER, async input => `sunny in ${String(input.location)}`);
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'test'}), registry);

    const outcome = await orchestrator
      .processMessage({
        sessionId: 's1',
        userId: 'u1',
        entries: [{role: 'user', content: 'weather?', timestamp: '2026-01-01T00:00:00.000Z'}],
      })
      .then(
        text => ({resolved: text}),
        (error: Error) => ({rejected: error.message})
      );
    const rejectionShownToModel = JSON.stringify(seen[1]?.messages.at(-1) ?? null);

    expect({outcome, rejectionNamesField: /location/.test(rejectionShownToModel)}).toEqual({
      outcome: {resolved: expect.stringContaining('It is sunny in Berlin.')},
      rejectionNamesField: true,
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool declares a JSON Schema as its `inputSchema`, and that same schema is handed verbatim to the providers to shape what the model sends. `ToolRegistry.execute` holds the model's input to it before the executor runs, so a tool receives only input its own schema accepts and a malformed call fails in one predictable way that the model can read and correct.

## Validating a call

- `ToolRegistry.execute` validates `input` against the resolved definition's `inputSchema` before calling the executor; input missing a `required` property is answered with a `ToolResponse` whose `result` names the missing property, and the executor is never invoked ([validated by: returns a rejection naming the missing required property and never runs the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L37)).
- Validation enforces `required`, declared types and `enum` only: it does not inject `additionalProperties: false`, coerce types or apply defaults, so valid input carrying an unlisted property reaches the executor unchanged.
- Rejection messages and log lines name the failing property path and the constraint that failed, and never a property value, so an identifying value in a rejected payload appears in neither the returned text nor any log line ([validated by: rejects a wrong-typed field by path and expected type without echoing the value in the result or the logs](../../src/orchestration/tools/registry.acceptance.test.ts#L50)).
- `execute` still throws `Unknown tool: <name>` for a name that was never registered; only input the schema rejects becomes a returned `ToolResponse`.

## Compiling schemas

- A static tool's schema is compiled once, at `register` time, so a schema that cannot be compiled throws from `register` with a message naming the tool, at startup rather than mid-conversation ([validated by: throws at register time for an uncompilable schema, naming the tool](../../src/orchestration/tools/registry.acceptance.test.ts#L68)).
- A function-valued `ToolDefinitionSource` resolves and compiles its schema per call, cached by the resolved schema object, so input is validated against the schema current at that call rather than a stale one.

## In the tool loop

- A rejection is a tool result, not an exception: the orchestrator feeds it back to the provider on the next round, so the model can correct the call and `processMessage` resolves rather than rejecting, with `DEFAULT_MAX_TOOL_ROUNDS` the bound that stops a retry cycle from spinning ([validated by: resolves processMessage after a rejected call and a corrected retry, showing the provider the rejection](../../src/orchestration/tools/registry.acceptance.test.ts#L81)).
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    this.tools.set(resolved.name, {definitionSource: definition, execute});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
